package com.foxnks.dockshift.data.db.entity

import androidx.room3.Entity
import androidx.room3.ForeignKey
import androidx.room3.Index
import androidx.room3.PrimaryKey

/**
 * Row of the `machine_faults` table: one fault reported on one machine.
 *
 * @property id identity, generated by the database.
 * @property machineId the machine (its key in `machines`).
 * @property type the `FaultType` name, e.g. "LIGHTS".
 * @property reportedOn ISO date it was reported ("2026-10-14").
 * @property fixedOn ISO date it was checked as fixed, or null while open.
 */
@Entity(
    tableName = "machine_faults",
    foreignKeys = [
        // A machine deleted for good takes its faults with it (only unused machines can be)
        ForeignKey(
            entity = MachineEntity::class,
            parentColumns = ["id"],
            childColumns = ["machineId"],
            onDelete = ForeignKey.CASCADE,
        ),
    ],
    // Speeds up "the faults of this machine"
    indices = [Index("machineId")],
)
data class MachineFaultEntity(
    @PrimaryKey(autoGenerate = true) val id: Long,
    val machineId: Long,
    val type: String,
    val reportedOn: String,
    val fixedOn: String?,
)
